public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IllegalArgumentException("OutputStream cannot be null");
    }
    if (message == null) {
        throw new IllegalArgumentException("Message cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    // Compute serialized size of the message
    int messageSize = schema.getSerializedSize(message);
    // Serialize message into a byte array
    byte[] data = new byte[messageSize];
    com.google.protobuf.CodedOutputStream cos = com.google.protobuf.CodedOutputStream.newInstance(data, 0, messageSize);
    schema.write(message, cos);
    cos.flush();
    // Write length prefix as varint
    int value = messageSize;
    while ((value & 0xFFFFFF80) != 0) {
        out.write((value & 0x7F) | 0x80);
        value >>>= 7;
    }
    out.write(value & 0x7F);
    // Write serialized bytes
    out.write(data);
    return messageSize;
}

