int addType(final String value) {
    if (value == null) {
        throw new IllegalArgumentException("type value cannot be null");
    }
    /* Ensure the type table exists */
    if (typeTable == null) {
        typeTable = new java.util.ArrayList<>();
    }
    /* Look for an existing type with the same value */
    for (int i = 0; i < typeTable.size(); i++) {
        Symbol sym = typeTable.get(i);
        if (sym != null) {
            // Most Symbol implementations expose the stored value via a getValue() or getName() method.
            try {
                String storedValue = sym.getValue(); // or sym.getName()
                if (value.equals(storedValue)) {
                    return i; // already exists
                }
            } catch (NoSuchMethodError | SecurityException | IllegalAccessException | java.lang.reflect.InvocationTargetException |
                     IllegalArgumentException e) {
                /* If getValue() is not available or cannot be accessed, fall back to toString()
                   comparison as a last resort. */
                if (value.equals(sym.toString())) {
                    return i;
                }
            }
        }
    }
    /* No existing type found – add a new Symbol */
    Symbol newSym = new Symbol(value);
    int newIndex = typeTable.size();
    typeTable.add(newSym);
    return newIndex;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType paramTy = (ParameterizedType) genericType;
    Class<?> rawTy = (Class<?>) paramTy.getRawType();
    if (!rawTy.isAssignableFrom(targetType)) {
        return null;
    }

    // Build mapping from type variables of all supertypes to concrete Types
    java.util.Map<TypeVariable<?>, Type> typeVarMap = new java.util.HashMap<>();
    boolean found = buildMapping(targetType, rawTy, typeVarMap);
    if (!found) {
        return null;
    }

    // Resolve each actual type argument of the genericType
    Type[] actualArgs = paramTy.getActualTypeArguments();
    Class<?>[] result = new Class<?>[actualArgs.length];
    for (int i = 0; i < actualArgs.length; i++) {
        Type resolved = resolveTypeArgument(actualArgs[i], typeVarMap);
        if (resolved instanceof Class<?>) {
            result[i] = (Class<?>) resolved;
        } else {
            return null; // cannot fully resolve to Class
        }
    }
    return result;
}

