void insertBefore(Bucket bucket) {
    if (bucket == null) {
        throw new IllegalArgumentException("bucket cannot be null");
    }
    if (this == bucket) {
        throw new IllegalArgumentException("cannot insert a bucket before itself");
    }

    // Detach this bucket from its current neighbors if necessary
    if (prev != null) {
        prev.next = next;
    }
    if (next != null) {
        next.prev = prev;
    }

    // Insert this bucket before the specified bucket
    this.prev = bucket.prev;
    this.next = bucket;

    if (bucket.prev != null) {
        bucket.prev.next = this;
    }
    bucket.prev = this;
}

