public synchronized void send(final String message) {
    if (message == null || message.isEmpty()) {
        return; // nothing to send
    }
    // Assume a Set<Socket> named 'clients' exists in the surrounding class
    if (clients == null) {
        return;
    }

    // Collect sockets that fail during sending so we can remove them later
    java.util.List<java.net.Socket> failedSockets = new java.util.ArrayList<>();

    for (java.net.Socket client : clients) {
        if (client == null) {
            failedSockets.add(client);
            continue;
        }
        try {
            java.io.OutputStream out = client.getOutputStream();
            byte[] msgBytes = (message + "\r\n").getBytes(java.nio.charset.StandardCharsets.UTF_8);
            out.write(msgBytes);
            out.flush();
        } catch (java.io.IOException e) {
            // Mark for removal if writing fails
            failedSockets.add(client);
        }
    }

    // Remove sockets that had errors
    for (java.net.Socket errSocket : failedSockets) {
        if (errSocket != null) {
            clients.remove(errSocket);
            try {
                errSocket.close();
            } catch (java.io.IOException ignored) { }
        }
    }
}

