    buffer[tail] = o;
    // Advance the tail index circularly
    tail = (tail + 1) % buffer.length;
    // Increment the count of stored events
    count++;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    // Ensure valid range
    if (start >= end || FETCH_DATA_DURATION <= 0) {
        return new java.util.ArrayList<>();
    }

    java.util.List<TimeRange> ranges = new java.util.ArrayList<>();
    long cursor = start;

    while (cursor < end) {
        long nextEnd = cursor + FETCH_DATA_DURATION;
        if (nextEnd > end) {
            nextEnd = end;
        }
        ranges.add(new TimeRange(cursor, nextEnd));
        cursor = nextEnd;
    }

    return ranges;
}

