static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be positive");
    }
    try {
        int year = (int) (timeBucket / 10000);
        int month = (int) ((timeBucket / 100) % 100);
        int day = (int) (timeBucket % 100);

        if (month < 1 || month > 12) {
            throw new IllegalArgumentException("Invalid month in timeBucket");
        }
        int daysInMonth = getDaysInMonth(year, month);
        if (day < 1 || day > daysInMonth) {
            throw new IllegalArgumentException("Invalid day in timeBucket");
        }

        int compressedDay = ((day - 1) / dayStep) * dayStep + 1;
        if (compressedDay > daysInMonth) {
            compressedDay = daysInMonth;
        }
        return year * 10000L + month * 100L + compressedDay;
    } catch (Exception ex) {
        throw new IllegalArgumentException("Error compressing timeBucket: " + ex.getMessage(), ex);
    }
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("String reference is null");
    }
    if (len < 0) {
        return 0;
    }
    final int strLen = str.length();
    if (index < 0 || index > strLen) {
        throw new IndexOutOfBoundsException(
                "index (" + index + ") is out of bounds for length " + strLen);
    }
    // Adjust len if it overflows the string
    final int effectiveLen = Math.min(len, strLen - index);
    if (effectiveLen == 0) {
        return 0;
    }

    int size = 0;
    int end = index + effectiveLen;
    for (int i = index; i < end; ) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            size += 1;
            i++;
        } else if (c <= 0x7FF) {
            size += 2;
            i++;
        } else {
            // Potential surrogate pair
            if (Character.isHighSurrogate(c) && i + 1 < end) {
                char low = str.charAt(i + 1);
                if (Character.isLowSurrogate(low)) {
                    size += 4;
                    i += 2;
                    continue;
                }
            }
            // Not a valid surrogate pair or incomplete pair
            size += 3;
            i++;
        }
    }
    return size;
}

