        return str.substring(strLength - suffixLength).equalsIgnoreCase(suffix);
    } else {
        return str.substring(strLength - suffixLength).equals(suffix);
    }
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null) {
        return segments;
    }
    int length = path.length();
    int segmentStart = (path.startsWith("/") && length > 0) ? 1 : 0;
    for (int i = segmentStart; i <= length; i++) {
        if (i == length || path.charAt(i) == '/') {
            String raw = path.substring(segmentStart, i);
            String decoded = raw;
            if (decode) {
                try {
                    decoded = java.net.URLDecoder.decode(raw, java.nio.charset.StandardCharsets.UTF_8.name());
                } catch (java.io.UnsupportedEncodingException e) {
                    // UTF-8 should always be supported; fall back to raw
                    decoded = raw;
                }
            }
            // Assuming PathSegmentImpl has a constructor that accepts raw and decoded forms
            segments.add(new PathSegmentImpl(raw, decoded));
            segmentStart = i + 1;
        }
    }
    return segments;
}

