public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }
    // Validate bounds
    double minX = box.getMinX();
    double maxX = box.getMaxX();
    double minY = box.getMinY();
    double maxY = box.getMaxY();
    if (minX > maxX || minY > maxY) {
        throw new IllegalArgumentException("Invalid box bounds");
    }

    double midX = (minX + maxX) / 2.0;
    Box2D left  = new Box2D(minX, minY, midX, maxY);
    Box2D right = new Box2D(midX, minY, maxX, maxY);
    return new Pair<>(left, right);
}

private void enlarge(final int size) {
    if (size <= 0) {
        return;
    }
    // Ensure the buffer can accommodate 'size' additional bytes.
    // If the buffer is null, initialize it with a default capacity.
    if (buf == null) {
        int initialCapacity = Math.max(32, size);
        buf = new byte[initialCapacity];
        pos = 0;
        return;
    }
    int oldCapacity = buf.length;
    int newCapacity = oldCapacity + size;
    // Grow at least twice the old capacity to reduce frequent resizing.
    int doubled = oldCapacity << 1;
    if (newCapacity < doubled) {
        newCapacity = doubled;
    }
    if (newCapacity < oldCapacity + size) {
        newCapacity = oldCapacity + size;
    }
    byte[] newBuf = new byte[newCapacity];
    System.arraycopy(buf, 0, newBuf, 0, pos);
    buf = newBuf;
}

