public void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new IllegalArgumentException("InputStream cannot be null");
    }
    // Read all bytes from the input stream into a byte array
    ByteArrayOutputStream bufferStream = new ByteArrayOutputStream();
    byte[] tmp = new byte[8192];
    int readBytes;
    while ((readBytes = in.read(tmp)) != -1) {
        bufferStream.write(tmp, 0, readBytes);
    }
    byte[] data = bufferStream.toByteArray();

    // Use reflection to safely assign the read data to a byte[] field
    // and reset any pointer-like integer field (pos, cursor, pointer, etc.).
    Class<?> cls = this.getClass();
    Field[] fields = cls.getDeclaredFields();
    for (Field field : fields) {
        try {
            field.setAccessible(true);
            Class<?> type = field.getType();
            if (type == byte[].class) {
                field.set(this, data);
            } else if (type == int.class) {
                String name = field.getName().toLowerCase();
                if (name.contains("pos") || name.contains("cursor") || name.contains("pointer")) {
                    field.setInt(this, 0);
                }
            }
        } catch (IllegalAccessException | IllegalArgumentException e) {
            // Ignore fields that cannot be accessed or set; the method should still complete
        }
    }
}

