@Override protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (value == null) {
        return null;
    }
    if (type != Character.class && type != char.class) {
        throw new Exception("Unsupported target type for character conversion: " + type);
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String s = (String) value;
        if (s.length() == 1) {
            return Character.valueOf(s.charAt(0));
        } else {
            throw new Exception("Cannot convert String to Character: string length is not 1");
        }
    }
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        if (intVal >= 0 && intVal <= Character.MAX_VALUE) {
            return Character.valueOf((char) intVal);
        } else {
            throw new Exception("Numeric value out of char range: " + intVal);
        }
    }
    // Fallback: try to use the string representation
    String str = value.toString();
    if (str.length() == 1) {
        return Character.valueOf(str.charAt(0));
    }
    throw new Exception("Cannot convert value of type " + value.getClass().getName() + " to Character");
}

public static boolean containsAnyIgnoreCase(String str, List<String> searchStrArray) {
    // If the source string is null, it cannot contain any other string
    if (str == null) {
        return false;
    }
    // If the list itself is null or empty, there is nothing to search for
    if (searchStrArray == null || searchStrArray.isEmpty()) {
        return false;
    }

    // Convert the source string to lower case once for case-insensitive comparison
    String lowerStr = str.toLowerCase(Locale.ROOT);

    for (String searchStr : searchStrArray) {
        // Skip null or empty entries – an empty string would always match, so it's ignored
        if (searchStr == null || searchStr.isEmpty()) {
            continue;
        }
        if (lowerStr.contains(searchStr.toLowerCase(Locale.ROOT))) {
            return true;
        }
    }
    return false;
}

public static int nextPrime(int desiredCapacity){
    // Handle trivial cases
    if (desiredCapacity <= 2) {
        return 2;
    }

    // Avoid negative or overflow values
    int candidate = desiredCapacity;
    // Ensure candidate is odd (even numbers > 2 cannot be prime)
    if ((candidate & 1) == 0) {
        candidate++;
    }

    while (true) {
        // Check for overflow before performing further operations
        if (candidate < 0) {
            throw new IllegalArgumentException("Desired capacity is too large to find a prime");
        }

        if (isPrime(candidate)) {
            return candidate;
        }

        // Increment to the next odd number
        if (candidate >= Integer.MAX_VALUE - 2) {
            // Next odd would overflow
            throw new IllegalArgumentException("No prime number available within integer range");
        }
        candidate += 2;
    }
}

