    }
    int endIndex = str.length() - 1;
    while (endIndex >= 0 && Character.isWhitespace(str.charAt(endIndex))) {
        endIndex--;
    }
    return endIndex == str.length() - 1 ? str : str.substring(0, endIndex + 1);
}

