@Override
public String readString() throws IOException {
    try {
        // Read the length of the string; conventionally -1 indicates null
        int length = in.readInt();
        if (length < 0) {
            return null;
        }
        if (length == 0) {
            return "";
        }
        // Read exactly 'length' bytes
        byte[] bytes = new byte[length];
        int offset = 0;
        while (offset < length) {
            int read = in.read(bytes, offset, length - offset);
            if (read == -1) {
                throw new EOFException("Unexpected end of stream while reading string");
            }
            offset += read;
        }
        // Convert bytes to a string using UTF-8 encoding
        try {
            return new String(bytes, "UTF-8");
        } catch (java.io.UnsupportedEncodingException e) {
            throw new IOException("UTF-8 encoding not supported", e);
        }
    } catch (java.io.EOFException e) {
        throw new IOException("Failed to read string: unexpected end of stream", e);
    }
}

private static int digitValue(final char c) {
    // ASCII digits 0-9
    if (c >= '0' && c <= '9') {
        return c - '0';
    }
    // ASCII letters a-z
    if (c >= 'a' && c <= 'z') {
        return c - 'a' + 10;
    }
    // ASCII letters A-Z
    if (c >= 'A' && c <= 'Z') {
        return c - 'A' + 10;
    }
    // Non-ASCII or unsupported characters
    return -1;
}

private Map<String, Object> buildContent(JsonObject jsonObject) {
    java.util.Map<String, Object> contentMap = new java.util.LinkedHashMap<>();
    if (jsonObject == null) {
        return contentMap;
    }
    try {
        for (java.util.Map.Entry<String, com.google.gson.JsonElement> entry : jsonObject.entrySet()) {
            String key = entry.getKey();
            com.google.gson.JsonElement val = entry.getValue();
            if (val == null || val.isJsonNull()) {
                contentMap.put(key, null);
                continue;
            }
            if (val.isJsonPrimitive()) {
                com.google.gson.JsonPrimitive prim = val.getAsJsonPrimitive();
                if (prim.isNumber()) {
                    contentMap.put(key, prim.getAsNumber());
                } else if (prim.isBoolean()) {
                    contentMap.put(key, prim.getAsBoolean());
                } else if (prim.isString()) {
                    contentMap.put(key, prim.getAsString());
                } else {
                    contentMap.put(key, prim.getAsString());
                }
            } else if (val.isJsonObject() || val.isJsonArray()) {
                contentMap.put(key, val);
            } else {
                contentMap.put(key, val.toString());
            }
        }
        if (jsonObject.has("ats")) {
            com.google.gson.JsonElement ats = jsonObject.get("ats");
            if (ats != null && !ats.isJsonNull()) {
                if (ats.isJsonPrimitive()) {
                    contentMap.put("ats", ats.getAsString());
                } else {
                    contentMap.put("ats", ats);
                }
            }
        }
    } catch (Exception ex) {
        contentMap.clear();
    }
    return contentMap;
}

