public final byte[] toByteArray(){
    // Compute the total number of bytes written across all buffers.
    int totalLength = 0;
    try {
        // If the buffers are stored in an array or list called `buffers`
        // and the length written in each buffer is tracked in an array `writeLengths`,
        // we sum those lengths to determine the final array size.
        if (buffers == null || writeLengths == null) {
            // If no buffers or lengths are available, return an empty array.
            return new byte[0];
        }
        for (int i = 0; i < writeLengths.length; i++) {
            totalLength += writeLengths[i];
        }

        // Allocate the result array once we know the total size.
        byte[] result = new byte[totalLength];
        int destPos = 0;

        // Copy each buffer's valid data into the result array.
        for (int i = 0; i < buffers.length; i++) {
            int len = writeLengths[i];
            if (len > 0) {
                System.arraycopy(buffers[i], 0, result, destPos, len);
                destPos += len;
            }
        }
        return result;
    } catch (Exception e) {
        // Wrap any unexpected issues in a RuntimeException to preserve API contract.
        throw new RuntimeException("Failed to convert buffer contents to byte array", e);
    }
}

public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\') {
            // Treat a backslash that is itself escaped as a literal backslash
            if (i > 0 && str.charAt(i - 1) == '\\') {
                sb.append('\\');
                continue;
            }
            if (i == len - 1) { // trailing backslash
                sb.append('\\');
                continue;
            }
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case '"':
                    sb.append('"');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'u':
                    if (i + 5 < len) {
                        String hex = str.substring(i + 2, i + 6);
                        try {
                            int code = Integer.parseInt(hex, 16);
                            sb.append((char) code);
                            i += 5;
                        } catch (NumberFormatException e) {
                            // If not a valid hex sequence, treat literally
                            sb.append('\\').append('u');
                            i++;
                        }
                    } else {
                        sb.append('\\').append('u');
                        i++;
                    }
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        int j = i + 1;
                        int val = 0;
                        int count = 0;
                        while (j < len && count < 3 && str.charAt(j) >= '0' && str.charAt(j) <= '7') {
                            val = (val << 3) + (str.charAt(j) - '0');
                            j++;
                            count++;
                        }
                        sb.append((char) val);
                        i = j - 1;
                    } else {
                        sb.append(next);
                        i++;
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

private static String javaCharset(String charset){
    if (charset == null) {
        return null;
    }
    String s = charset.trim();
    if (s.isEmpty()) {
        return null;
    }
    // Normalise to upper‑case for comparison
    String key = s.toUpperCase(java.util.Locale.ROOT);
    switch (key) {
        case "US-ASCII":
            return "US-ASCII";
        case "UTF-8":
        case "UTF8":
            return "UTF-8";
        case "ISO-8859-1":
        case "LATIN1":
        case "ISO-IR-100":
            return "ISO-8859-1";
        case "ISO-8859-2":
            return "ISO-8859-2";
        case "ISO-8859-5":
            return "ISO-8859-5";
        case "ISO-8859-15":
            return "ISO-8859-15";
        case "ISO-2022-JP":
            return "ISO-2022-JP";
        case "WINDOWS-1252":
            return "windows-1252";
        case "WINDOWS-1251":
            return "windows-1251";
        case "KOI8-R":
        case "KOI8R":
            return "KOI8-R";
        case "KOI8-U":
        case "KOI8U":
            return "KOI8-U";
        case "MACINTOSH":
            return "Macintosh";
        case "X-MAC-CYRILLIC":
            return "x-mac-cyrillic";
        case "GB2312":
            return "GB2312";
        default:
            break;
    }
    // Try to validate using java.nio.charset
    try {
        java.nio.charset.Charset cs = java.nio.charset.Charset.forName(s);
        return cs.name();
    } catch (Exception e) {
        return null;
    }
}

