public short readShort(final int offset){
    // Retrieve the underlying byte array and its length
    final byte[] data = this.bytes;
    final int len = data.length;

    // Validate the offset to avoid out-of-range access
    if (offset < 0 || offset + 1 >= len) {
        throw new IllegalArgumentException("Invalid offset: " + offset);
    }

    // Combine the two bytes into a signed short value
    // Shift the first byte (most significant) and mask the second byte
    return (short) ((data[offset] << 8) | (data[offset + 1] & 0xFF));
}

private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    // If the input array is null, create a new array of size 1 with the provided component type
    if (array == null) {
        if (newArrayComponentType == null) {
            throw new IllegalArgumentException("Both array and newArrayComponentType cannot be null");
        }
        Object newArray = java.lang.reflect.Array.newInstance(newArrayComponentType, 1);
        return newArray;
    }

    // Validate that the provided object is indeed an array
    Class<?> arrayClass = array.getClass();
    if (!arrayClass.isArray()) {
        throw new IllegalArgumentException("The provided object is not an array");
    }

    Class<?> componentType = arrayClass.getComponentType();
    int oldLength = java.lang.reflect.Array.getLength(array);
    Object newArray = java.lang.reflect.Array.newInstance(componentType, oldLength + 1);

    // Copy contents from the original array to the new array
    try {
        System.arraycopy(array, 0, newArray, 0, oldLength);
    } catch (Throwable t) {
        // Wrap and rethrow as a runtime exception to preserve method contract
        throw new RuntimeException("Error copying array elements", t);
    }

    return newArray;
}

private int computeBinaryLog(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer");
    }
    // Integer.numberOfLeadingZeros(n) returns the number of zero bits preceding the
    // highest-order (leftmost) one-bit. For a positive integer n, the number of bits
    // required to represent n is 32 - numberOfLeadingZeros(n).
    return 32 - Integer.numberOfLeadingZeros(n);
}

private Set<V> intersection(Set<V> set1, Set<V> set2) {
    // Handle null inputs gracefully by returning an empty set
    if (set1 == null || set2 == null) {
        return new HashSet<>();
    }

    // If the two sets are actually the same instance, avoid unnecessary work
    if (set1 == set2) {
        return new HashSet<>(set1);
    }

    // Iterate over the smaller set to reduce lookup operations
    Set<V> smaller = set1.size() <= set2.size() ? set1 : set2;
    Set<V> larger  = smaller == set1 ? set2 : set1;

    Set<V> result = new HashSet<>(smaller.size());
    for (V element : smaller) {
        if (larger.contains(element)) {
            result.add(element);
        }
    }
    return result;
}

