    try {
        for (int i = 0; i < properties.size(); i++) {
            KeyStringValuePair kvp = properties.get(i);
            if (kvp == null) {
                continue; // Skip null entries
            }
            String key;
            String value;
            try {
                key = kvp.getKey();
                value = kvp.getValue();
