            // Add the property to the JsonObject; using addProperty for String values
            result.addProperty(key, value);
        }
    } catch (Exception e) {
        // If any unexpected exception occurs, we return an empty JsonObject
        return new JsonObject();
    }
    return result;
}

protected int removeUnusedNodes() {
    class Visitor {
        int visit(Category node) {
            if (node == null) {
                return 0;
            }
            int removed = 0;
            List<Category> children = node.getChildren();
            if (children == null) {
                return 0;
            }
            Iterator<Category> it = children.iterator();
            while (it.hasNext()) {
                Category child = it.next();
                if (child == null) {
                    continue;
                }
                if (!child.isActive()) {
                    // Count the entire subtree rooted at this inactive child
                    removed += countAllNodes(child);
                    // Remove the child from its parent’s list
                    it.remove();
                } else {
                    // Recurse into active child
                    removed += visit(child);
                }
            }
            return removed;
        }

        int countAllNodes(Category node) {
            if (node == null) {
                return 0;
            }
            int count = 1; // count the node itself
            List<Category> children = node.getChildren();
            if (children != null) {
                for (Category child : children) {
                    count += countAllNodes(child);
                }
            }
            return count;
        }
    }
    Visitor visitor = new Visitor();
    try {
        return visitor.visit(this);
    } catch (Exception e) {
        // In case of unexpected errors, return 0 to indicate no nodes were removed
        return 0;
    }
}

