private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null || stop == null) {
        throw new IllegalArgumentException("Start and stop nodes must not be null");
    }

    // Start the circulator at the provided node and direction
    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);
    // Keep track of visited nodes to avoid infinite loops
    java.util.Set<Node> visited = new java.util.HashSet<>();

    while (circ != null) {
        Node current = circ.getNode();
        // If the current node meets the predicate, return the circulator
        if (predicate.test(current)) {
            return circ;
        }
        // If we've reached the stop node, terminate the search
        if (current.equals(stop)) {
            break;
        }
        // If we are revisiting a node, break to avoid an infinite loop
        if (!visited.add(current)) {
            break;
        }
        // Advance to the next node on the outer face
        circ = circ.next();
    }
    return circ;
}

