        return this;
    }
    if (byteArrayValue != null) {
        if (byteOffset < 0 || byteOffset > byteArrayValue.length - byteLength) {
            throw new IllegalArgumentException("byteOffset/byteLength out of bounds");
        }
    }
    // Compute the new position and ensure capacity
    final int newPos = pos + byteLength;
    if (newPos > buf.length) {
        // If a private expand method exists, use it; otherwise, grow the buffer manually
        final int newCap = Math.max(newPos, buf.length + 20);
        final byte[] newBuf = new byte[newCap];
        System.arraycopy(buf, 0, newBuf, 0, pos);
        buf = newBuf;
    }
    // Copy data (or zeros if the source array is null)
    if (byteArrayValue == null) {
        for (int i = pos; i < newPos; ++i) {
