public static String deleteAny(String inString, String charsToDelete) {
    // Handle null inputs gracefully.
    if (inString == null) {
        return null;
    }
    if (charsToDelete == null || charsToDelete.isEmpty()) {
        return inString;
    }

    // Use a boolean array to mark characters that should be deleted.
    // This approach is efficient for the full BMP (Unicode 16-bit) and avoids
    // repeated lookups in a HashSet.
    boolean[] deleteMask = new boolean[65536];
    for (int i = 0; i < charsToDelete.length(); i++) {
        deleteMask[charsToDelete.charAt(i)] = true;
    }

    // Build the resulting string by skipping characters marked for deletion.
    StringBuilder result = new StringBuilder(inString.length());
    for (int i = 0; i < inString.length(); i++) {
        char c = inString.charAt(i);
        if (!deleteMask[c]) {
            result.append(c);
        }
    }

    return result.toString();
}

