int addConstantNameAndType(final String name, final String descriptor){
    if (name == null || descriptor == null) {
        throw new IllegalArgumentException("Name and descriptor must not be null");
    }
    if (this.constantPool == null) {
        throw new IllegalStateException("Constant pool is not initialized");
    }
    // Use a simple pair key for lookup
    final class Key {
        final String n, d;
        Key(String n, String d){ this.n=n; this.d=d; }
        @Override public boolean equals(Object o){
            if (this==o) return true;
            if (!(o instanceof Key)) return false;
            Key k=(Key)o;
            return n.equals(k.n) && d.equals(k.d);
        }
        @Override public int hashCode(){ return n.hashCode()*31 + d.hashCode(); }
    }
    Key key = new Key(name, descriptor);
    Integer existing = this.constantIndexMap.get(key);
    if (existing != null) {
        return existing;
    }
    // Create the new constant pool entry
    ConstantNameAndTypeInfo entry;
    try {
        entry = new ConstantNameAndTypeInfo(name, descriptor);
    } catch (Exception e) {
        throw new RuntimeException("Failed to create ConstantNameAndTypeInfo", e);
    }
    this.constantPool.add(entry);
    int idx = this.constantPool.size() - 1;
    this.constantIndexMap.put(key, idx);
    return idx;
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    // Remove surrounding quotes or braces
    String work = input;
    if (work.length() >= 2) {
        char first = work.charAt(0);
        char last = work.charAt(work.length() - 1);
        if ((first == '"' && last == '"') || (first == '{' && last == '}')) {
            work = work.substring(1, work.length() - 1);
        }
    }

    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < work.length(); i++) {
        char c = work.charAt(i);
        if (c == '\\' && i + 1 < work.length()) {
            char next = work.charAt(++i);
            switch (next) {
                case 'n':
                    sb.append('\n');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                case '"':
                    sb.append('"');
                    break;
                case '{':
                    sb.append('{');
                    break;
                case '}':
                    sb.append('}');
                    break;
                case 'a':
                    sb.append('\u0007');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case 'v':
                    sb.append('\u000B');
                    break;
                case 'x':
                    // Hexadecimal escape \xHH
                    int hexLen = 0;
                    int hexVal = 0;
                    while (i + 1 < work.length() && hexLen < 2) {
                        char h = work.charAt(i + 1);
                        int digit = Character.digit(h, 16);
                        if (digit == -1) {
                            break;
                        }
                        hexVal = (hexVal << 4) + digit;
                        i++;
                        hexLen++;
                    }
                    sb.append((char) hexVal);
                    break;
                case 'u':
                    // Unicode escape \uHHHH
                    int uLen = 0;
                    int uVal = 0;
                    while (i + 1 < work.length() && uLen < 4) {
                        char h = work.charAt(i + 1);
                        int digit = Character.digit(h, 16);
                        if (digit == -1) {
                            break;
                        }
                        uVal = (uVal << 4) + digit;
                        i++;
                        uLen++;
                    }
                    sb.append((char) uVal);
                    break;
                default:
                    if (next >= '0' && next <= '7') {
                        // Octal escape \NNN (up to 3 octal digits)
                        int octVal = next - '0';
                        int octCount = 1;
                        while (i + 1 < work.length() && octCount < 3) {
                            char d = work.charAt(i + 1);
                            if (d >= '0' && d <= '7') {
                                octVal = (octVal << 3) + (d - '0');
                                i++;
                                octCount++;
                            } else {
                                break;
                            }
                        }
                        sb.append((char) octVal);
                    } else {
                        // Unknown escape: keep as is
                        sb.append(next);
                    }
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

public static String[] concatenateStringArrays(String[] array1, String[] array2) {
    // If both arrays are null, return null as specified.
    if (array1 == null && array2 == null) {
