    // Determine lengths of the non-null arrays (treat null as length 0).
    int len1 = (array1 == null) ? 0 : array1.length;
    int len2 = (array2 == null) ? 0 : array2.length;

    // Create the result array with combined size.
    String[] result = new String[len1 + len2];

    // Copy elements from the first array if it is not null.
    if (array1 != null) {
        System.arraycopy(array1, 0, result, 0, len1);
    }

    // Copy elements from the second array if it is not null.
    if (array2 != null) {
        System.arraycopy(array2, 0, result, len1, len2);
    }

    return result;
}

private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel){
    if (bucketsByLabel == null || labels == null) {
        return;
    }
    if (minLabel <= 0 || minLabel >= bucketsByLabel.size()) {
        // No action needed for negative, zero, or out-of-range minLabel
        return;
    }
    Set<Integer> source = bucketsByLabel.get(minLabel);
    if (source == null || source.isEmpty()) {
        return;
    }
    Set<Integer> dest = bucketsByLabel.get(0);
    if (dest == null) {
        dest = new java.util.HashSet<>();
        bucketsByLabel.set(0, dest);
    }
    for (Integer v : source) {
        dest.add(v);
        if (v != null && v >= 0 && v < labels.size()) {
            labels.set(v, 0);
        }
    }
    source.clear();
}

