private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    // Handle removal of the first node
    if (node == first) {
        first = node.next;
        if (node == last) {
            last = null;
        }
        size--;
        node.item = null;
        node.next = null;
        return true;
    }
    // Search for the predecessor of the node to remove
    ListNodeImpl<E> prev = first;
    while (prev != null && prev.next != node) {
        prev = prev.next;
    }
    if (prev == null) {
        // Node not found in the list
        return false;
    }
    prev.next = node.next;
    if (node == last) {
        last = prev;
    }
    size--;
    node.item = null;
    node.next = null;
    return true;
}

public List<SequenceRange> buildSequenceRanges() {
    // Create a result list to hold the sequence ranges
    List<SequenceRange> ranges = new ArrayList<>();

    try {
        // Retrieve the current profile segment snapshots from this instance.
        // If the method or field is null, we simply return an empty list.
        List<?> snapshots = this.getCurrentProfileSegmentSnapshots();
        if (snapshots == null) {
            return ranges; // empty list
        }

        // Iterate over each snapshot and construct a SequenceRange.
        for (Object snapshotObj : snapshots) {
            if (snapshotObj == null) {
                continue; // Skip null entries
            }

            // We expect each snapshot to provide a start index and length or end index.
            // Use reflection to obtain these values in a defensive way.
            int start = -1;
            int length = -1;
            try {
                // Attempt to read "getStart()" method
                java.lang.reflect.Method startMethod = snapshotObj.getClass().getMethod("getStart");
                Object startVal = startMethod.invoke(snapshotObj);
                if (startVal instanceof Number) {
                    start = ((Number) startVal).intValue();
                }
                // Attempt to read "getLength()" method
                java.lang.reflect.Method lengthMethod = snapshotObj.getClass().getMethod("getLength");
                Object lengthVal = lengthMethod.invoke(snapshotObj);
                if (lengthVal instanceof Number) {
                    length = ((Number) lengthVal).intValue();
                }
            } catch (ReflectiveOperationException e) {
                // If reflection fails, skip this snapshot
                continue;
            }

            // Validate extracted values
            if (start < 0 || length < 0) {
                continue; // skip invalid ranges
            }

            // Construct a SequenceRange using the obtained start and length.
            // We assume SequenceRange has a constructor (int start, int length).
            SequenceRange range = new SequenceRange(start, length);
            ranges.add(range);
        }
    } catch (Exception e) {
        // Any unexpected exception is wrapped into an IllegalStateException
        // to signal a failure in building the sequence ranges.
        throw new IllegalStateException("Failed to build sequence ranges", e);
    }

    return ranges;
}

