private Pair<List<Integer>,Long> computeSuffixSum(List<Integer> bounds){
    // Handle null input
    if (bounds == null) {
        return Pair.of(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    // Prepare the suffix list with the same size
    List<Integer> suffix = new ArrayList<>(n);
    long total = 0L;
    long accumulator = 0L;

    // Compute suffix sums in reverse order
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException(\"Element at index \" + i + \" is null\");
        }
        accumulator += val;
        suffix.add((int) accumulator);
        total += val;
    }

    // Reverse to maintain the original order: suffix[i] corresponds to sum of bounds[i..n-1]
    Collections.reverse(suffix);
    return Pair.of(suffix, total);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new IllegalArgumentException("Array cannot be null");
    }
    if (from > to) {
        throw new IllegalArgumentException("The 'from' index must be less than or equal to the 'to' index");
    }
    int length = arr.length;
    if (from < 0 || to >= length) {
        throw new IndexOutOfBoundsException("Indices are out of bounds. Array length: " + length);
    }
    for (int i = from, j = to; i < j; i++, j--) {
        V temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}

private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null) {
        throw new NullPointerException("Source list must not be null");
    }
    // If we are asked to move nodes from this list to itself or the list is empty,
    // nothing needs to be done.
    if (list == this || list.isEmpty()) {
        return;
    }
    // Transfer nodes one by one. We capture the next node before removing
    // the current node so that we can continue iterating safely.
    ListNodeImpl<E> current = list.firstNode;
    while (current != null) {
        ListNodeImpl<E> next = current.next;
        // Remove from the source list
        list.removeListNode(current);
        // Add to this list
        this.addListNode(current);
        current = next;
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null) {
        return prefix == null;
    }
    // If str is not null but prefix is null, it does not start with null
    if (prefix == null) {
        return false;
    }

    // Quick length check: a longer prefix cannot match
    if (prefix.length() > str.length()) {
        return false;
    }

    // Use regionMatches to allow optional case-insensitive comparison
    return str.regionMatches(ignoreCase, 0, prefix, 0, prefix.length());
}

