public ByteVector putInt(final int intValue){
    // Ensure the underlying buffer has enough space for 4 more bytes
    if (len > buffer.length - 4) {
        int newCap = Math.max(4, buffer.length * 2);
        byte[] newBuf = new byte[newCap];
        System.arraycopy(buffer, 0, newBuf, 0, len);
        buffer = newBuf;
    }
    // Write the int in big‑endian order
    buffer[len++] = (byte) (intValue >> 24);
    buffer[len++] = (byte) (intValue >> 16);
    buffer[len++] = (byte) (intValue >> 8);
    buffer[len++] = (byte) intValue;
    return this;
}

