        throw new IllegalArgumentException("vertices must not be null");
    }

    int size = vertices.size();
    // An empty set or a single vertex is trivially a clique
    if (size <= 1) {
        return true;
    }

    // All vertices must belong to the graph
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            return false;
        }
    }

    // Check all unordered pairs of vertices
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (!v1.equals(v2)) {
                // For undirected graphs a single edge check is enough.  
                // For directed graphs, if either direction exists, we consider it sufficient;
                // this behaviour is conservative and prevents false positives.
                if (!graph.containsEdge(v1, v2) && !graph.containsEdge(v2, v1)) {
                    return false;
                }
            }
        }
    }

    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return result;
    }
    // Copy and sort keys using natural ordering
    List<K> sorted = new ArrayList<>(keys);
    sorted.sort(new Comparator<>() {
        @Override
        public int compare(K o1, K o2) {
            if (o1 == null || o2 == null) {
                throw new IllegalArgumentException("Key cannot be null");
            }
            try {
                return ((Comparable) o1).compareTo(o2);
            } catch (ClassCastException e) {
                throw new IllegalArgumentException("Key does not implement Comparable", e);
            }
        }
    });
    // Compute lower bound for each key
    for (K key : keys) {
        if (key == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        int lo = 0;
        int hi = sorted.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            K midVal = sorted.get(mid);
            int cmp;
            try {
                cmp = ((Comparable) midVal).compareTo(key);
            } catch (ClassCastException e) {
                throw new IllegalArgumentException("Key does not implement Comparable", e);
            }
            if (cmp < 0) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        int lowerIndex = lo - 1;
        result.add(lowerIndex >= 0 ? lowerIndex : -1);
    }
    return result;
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("descriptor must not be null");
    }

    String types = descriptor;
    int idx = descriptor.indexOf('(');
    if (idx != -1) { // method descriptor
        int end = descriptor.indexOf(')', idx);
        if (end == -1) {
            throw new IllegalArgumentException("Invalid method descriptor: " + descriptor);
        }
        types = descriptor.substring(idx + 1, end);
    }

    int pos = 0;
    final int len = types.length();
    while (pos < len) {
        char c = types.charAt(pos);
        if (c == 'L') { // object
            int endSemicol = types.indexOf(';', pos);
            if (endSemicol == -1) {
                throw new IllegalArgumentException("Invalid descriptor: " + types);
            }
            pos = endSemicol + 1;
            output.pop(); // object types occupy one slot
        } else if (c == '[') { // array
            // consume all '['
            while (pos < len && types.charAt(pos) == '[') {
                pos++;
            }
            if (pos >= len) {
                throw new IllegalArgumentException("Invalid descriptor: " + types);
            }
            // now base type
            if (types.charAt(pos) == 'L') {
                int endSemicol = types.indexOf(';', pos);
                if (endSemicol == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: " + types);
                }
                pos = endSemicol + 1;
            } else {
                pos++; // primitive base
            }
            output.pop(); // arrays occupy one slot regardless of element type
        } else { // primitive or void
            switch (c) {
                case 'J': // long
                case 'D': // double
                    output.pop();
                    output.pop(); // long and double occupy two slots
                    break;
                case 'V': // void - nothing to pop
                    break;
                case 'B':
                case 'C':
                case 'F':
                case 'I':
                case 'S':
                case 'Z':
                    output.pop(); // all other primitives occupy one slot
                    break;
                default:
                    throw new IllegalArgumentException("Invalid descriptor char: " + c);
            }
            pos++;
        }
    }
}

