private List<Integer> computeUpperBounds(List<K> keys){
    // If input list is null or empty, return an empty list
    if (keys == null || keys.isEmpty()){
        return new ArrayList<>();
    }

    // Prepare a copy of the keys as Integers for sorting
    List<Integer> sorted = new ArrayList<>();
    for (K k : keys){
        if (k == null){
            sorted.add(null);
        } else {
            if (!(k instanceof Integer)){
                // Invalid element type; throw a descriptive exception
                throw new IllegalArgumentException("Element in keys list is not an Integer: " + k);
            }
            sorted.add((Integer) k);
        }
    }

    // Sort the list, placing nulls first to avoid comparison errors
    sorted.sort(Comparator.nullsFirst(Integer::compareTo));

    List<Integer> result = new ArrayList<>(keys.size());

    // For each key, find the minimal >= key (ceiling) in the sorted list
    for (K k : keys){
        if (k == null){
            result.add(null);
            continue;
        }

        // Safe cast since we already validated the type
        int keyValue = (Integer) k;

        // Binary search to find insertion point for keyValue
        int idx = Collections.binarySearch(sorted, keyValue, Comparator.nullsFirst(Integer::compareTo));
        if (idx < 0){
            idx = -idx - 1; // insertion point if not found
        }

        // Skip any nulls that might appear in the sorted list
        while (idx < sorted.size() && sorted.get(idx) == null){
            idx++;
        }

        if (idx < sorted.size()){
            result.add(sorted.get(idx));
        } else {
            // No value >= keyValue found; indicate by null
            result.add(null);
        }
    }

    return result;
}

public static String encodeTemplateNames(String s) {
    if (s == null) {
        return null;
    }
    try {
        // Percent-encode '{' as %7B and '}' as %7D
        return s.replace("{", "%7B").replace("}", "%7D");
    } catch (Exception e) {
        // In the unlikely event of an unexpected error, return the original string
        return s;
    }
}

public static boolean equals(Point2D p1, Point2D p2){
    // Handle reference equality and nulls
    if (p1 == p2) {
        return true;
    }
    if (p1 == null || p2 == null) {
        return false;
    }
    // Use a tolerance for floating-point comparison
    final double tolerance = 1e-9;
    double dx = p1.getX() - p2.getX();
    double dy = p1.getY() - p2.getY();
    return Math.abs(dx) <= tolerance && Math.abs(dy) <= tolerance;
}

