static String[] toNoNullStringArray(Object[] array){
    if (array == null) {
        return null;
    }
    int nullCount = 0;
    for (Object obj : array) {
        if (obj == null) {
            nullCount++;
        } else if (!(obj instanceof String)) {
            throw new ClassCastException("Array element is not a String: " + obj);
        }
    }
    if (nullCount == 0) {
        // Safe to cast since elements are all Strings
        return (String[]) array;
    }
    String[] result = new String[array.length - nullCount];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null) {
            result[idx++] = (String) obj;
        }
    }
    return result;
}

public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1;
    }
    int lastSeparator = indexOfLastSeparator(filename);
    if (lastSeparator > dotIndex) {
        return -1;
    }
    return dotIndex;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    // Handle negative threshold values: treat as no expiration
    if (expiredThreshold < 0) {
        return false;
    }
    long now;
    try {
        now = System.currentTimeMillis();
    } catch (Exception e) {
        // If system time retrieval fails, conservatively do not expire
        return false;
    }
    // If the timestamp is in the future, the metric is definitely not expired
    if (timestamp > now) {
        return false;
    }
    // Determine if the elapsed time since the timestamp exceeds the allowed threshold
    try {
        return (now - timestamp) > expiredThreshold;
    } catch (ArithmeticException e) {
        // In case of overflow, consider it not expired to avoid false positives
        return false;
    }
}

Edge edgeToNext() {
    try {
        // If either node is unknown, we cannot determine an edge.
        if (previousNode == null || nextNode == null) {
            return null;
        }

        Node fromNode = previousNode;
        Node toNode   = nextNode;

        // Resolve virtual nodes to their real counterparts if necessary.
        if (fromNode.isVirtual()) {
            fromNode = fromNode.getRealNode();
        }
        if (toNode.isVirtual()) {
            toNode = toNode.getRealNode();
        }

        // Attempt to fetch the edge in the forward direction.
        Edge edge = graph.getEdge(fromNode, toNode);
        if (edge == null) {
            // If the graph is undirected or stored only in one direction,
            // try the reverse direction as a fallback.
            edge = graph.getEdge(toNode, fromNode);
        }

        return edge;
    } catch (Exception ex) {
        // The method is expected to return an edge or null; any failure is wrapped
        // to indicate a runtime issue in the traversal logic.
        throw new RuntimeException("Unable to retrieve edge connecting previous to next node", ex);
    }
}

public static boolean substringMatch(CharSequence str,int index,CharSequence substring){
    // Guard against null inputs
    if (str == null || substring == null) {
        return false;
    }
    int strLen = str.length();
    int subLen = substring.length();

    // Index must be within the bounds of str and allow the substring to fit
    if (index < 0 || index + subLen > strLen) {
        return false;
    }

    // Empty substring always matches
    if (subLen == 0) {
        return true;
    }

    // Compare characters one by one
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

protected void append(LoggingEvent event) {
    // Null check for the event itself
    if (event == null) {
        return;
    }

    // Extract the message from the event.
    // Assuming LoggingEvent exposes a getMessage() that returns a String.
    String message = event.getMessage();
    if (message == null) {
        return;
    }

    // Writing the message to each connected client.
    // It is assumed that there is a collection named 'clients' that holds objects
    // with a write(String) method capable of throwing IOException.
    synchronized (clients) {
        for (Client client : clients) {
            try {
                client.write(message);
            } catch (IOException e) {
                // Log the error to standard error. In a real implementation you might
                // delegate to an error handler or a logger.
                System.err.println("Failed to write log event to client: " + e.getMessage());
            } catch (Exception e) {
                // Catch any other unexpected exceptions so that one bad client
                // does not prevent other clients from receiving the log.
                System.err.println("Unexpected error while writing to client: " + e.getMessage());
            }
        }
    }
}

public static String toString(final char ch){
    // Short‑circuit for empty array or 0 volume
    // Use intern to cache the one‑character strings
    try {
        return String.valueOf(ch).intern();
    } catch (RuntimeException e) {
        // Fallback to a new String if intern fails (unlikely)
        return new String(new char[]{ch});
    }
}

private void checkIfPackedField() throws IOException {
    // Verify that the parser has an input source to read from
    if (input == null) {
        throw new IOException("Input source is not initialized");
    }

    // Read the next field tag. A tag of 0 indicates the end of input.
    int tag;
    try {
        tag = input.readTag();
    } catch (IOException e) {
        throw new IOException("Failed to read field tag", e);
    }

    if (tag == 0) {
        // No more fields to process
        return;
    }

    // Extract wire type from lower 3 bits of the tag
    int wireType = tag & 0x7;
    // Store the current field number for potential later use
    currentFieldNumber = tag >>> 3;

    // In protobuf encoding, wire type 2 (length-delimited) indicates a packed
    // repeated field for primitive numeric types.
    isPackedField = (wireType == 2);
}

public int readTag() throws IOException {
    int result = 0;
    int shift = 0;
    while (shift < 32) {
        int b = input.read();
        if (b == -1) {
            // EOF reached before any byte was read
            if (shift == 0) {
                return 0;
            }
            // EOF in the middle of a varint indicates a truncated tag
            throw new IOException("Truncated message while reading tag");
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    throw new IOException("Tag is too long.");
}

final ByteVector put11(final int byteValue1, final int byteValue2) {
    // validate byte values are in the 0-255 range
    if ((byteValue1 & 0xFFFFFF00) != 0 || (byteValue2 & 0xFFFFFF00) != 0) {
        throw new IllegalArgumentException("byte values must be between 0 and 255");
    }

    // ensure capacity to hold two more bytes
    if (size > Integer.MAX_VALUE - 2) {
        throw new IllegalStateException("ByteVector too large to add two more bytes");
    }
    if ((size + 2) > vector.length) {
        int newCapacity = vector.length << 1;
        if (newCapacity < size + 2) {
            newCapacity = size + 2;
        }
        byte[] newVector = new byte[newCapacity];
        System.arraycopy(vector, 0, newVector, 0, size);
        vector = newVector;
    }

    // add the bytes
    vector[size] = (byte) byteValue1;
    vector[size + 1] = (byte) byteValue2;
    size += 2;

    return this;
}

private String buildContentRange(){
    try{
        Field startField = null;
        Field endField = null;
        Field totalField = null;
        Class<?> clazz = this.getClass();
        for(Field f: clazz.getDeclaredFields()){
            String n = f.getName().toLowerCase();
            if(startField==null && (n.contains("start") || n.contains("from") || n.contains("first") || n.contains("firstbyte"))){
                startField = f;
            }
            if(endField==null && (n.contains("end") || n.contains("to") || n.contains("last") || n.contains("lastbyte"))){
                endField = f;
            }
            if(totalField==null && (n.contains("total") || n.contains("size") || n.contains("contentlength") || n.contains("entitysize"))){
                totalField = f;
            }
        }
        long start = 0, end = 0, total = 0;
        if(startField!=null){
            startField.setAccessible(true);
            Object v = startField.get(this);
            if(v instanceof Number) start = ((Number)v).longValue();
        }
        if(endField!=null){
            endField.setAccessible(true);
            Object v = endField.get(this);
            if(v instanceof Number) end = ((Number)v).longValue();
        }
        if(totalField!=null){
            totalField.setAccessible(true);
            Object v = totalField.get(this);
            if(v instanceof Number) total = ((Number)v).longValue();
        }
        if(start<0 || end<0 || start> end){
            return "bytes */*";
        }
        if(total>0){
            return "bytes " + start + "-" + end + "/" + total;
        }
        return "bytes " + start + "-" + end + "/*";
    }catch(Exception e){
        return "bytes */*";
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file cannot be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new FileNotFoundException("File not found or is not a regular file: " + file);
    }
    if (timeRanges == null) {
        throw new IllegalArgumentException("timeRanges cannot be null");
    }
    List<ThreadSnapshot> result = new ArrayList<>();

    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        List<String> snapshotLines = new ArrayList<>();
        while ((line = br.readLine()) != null) {
            if (line.trim().isEmpty()) {
                if (!snapshotLines.isEmpty()) {
                    String snapshotData = String.join(System.lineSeparator(), snapshotLines);
                    ThreadSnapshot snapshot = null;
                    try {
                        snapshot = ThreadSnapshot.parse(snapshotData); // Adjust method name as per actual API
                    } catch (Exception e) {
                        // Skip malformed snapshot
                        snapshotLines.clear();
                        continue;
                    }
                    if (isWithinTimeRanges(snapshot, timeRanges)) {
                        result.add(snapshot);
                    }
                    snapshotLines.clear();
                }
            } else {
                snapshotLines.add(line);
            }
        }
        // Process the last snapshot if file doesn't end with a delimiter
        if (!snapshotLines.isEmpty()) {
            String snapshotData = String.join(System.lineSeparator(), snapshotLines);
            ThreadSnapshot snapshot = null;
            try {
                snapshot = ThreadSnapshot.parse(snapshotData); // Adjust method name as per actual API
            } catch (Exception e) {
                // Skip malformed snapshot
                snapshotLines.clear();
                return result;
            }
            if (isWithinTimeRanges(snapshot, timeRanges)) {
                result.add(snapshot);
            }
        }
    } catch (IOException e) {
        throw new IOException("Failed to read thread snapshots from file: " + file, e);
    }
    return result;
}
